
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_eb88_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_eb88", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.315111756118491e+00, -4.233293993902030e+00, -4.118735807041883e+00, -3.960228554402204e+00, -3.744627449003903e+00, -3.458481785729772e+00, -3.091839447410984e+00, -2.645008898241598e+00, -2.137240586628959e+00, -1.608947841328392e+00, -1.093352098890848e+00, -7.104824183869763e-01, -6.034555844848395e-01, -5.025869623729001e-01, -3.707749473515620e-01, -2.461185150813107e-01, -1.543468998265627e-01, -9.562123519338248e-02, -6.095873246372647e-02, -4.171645732086155e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


